window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8ceca6e6a74515da"]={"versions": [{"id": "FIG-8ceca6e6a74515da", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Modellierungsdiagramm zur Verknüpfung von Hardware- und Softwareressourcen in AUTOSAR Classic. Das Diagramm veranschaulicht das Zusammenspiel zwischen dem ECU Resource Template (Hardwareressourcenbeschreibung eines Steuergeräts/Sensors) und dem Software Component Template (SW-C Template) bei der Bereitstellung („Shipment“) einer Sensor-Komponente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ECU Resource Template</strong>: Dokumenten-/Artefaktcontainer, der die physische Hardwareressource <code>Sensor</code> beschreibt. Die Sensor-Entität verfügt über einen eingehenden physikalischen/elektrischen Signalfluss (Pfeil links) und einen ausgehenden Signalfluss (Pfeil rechts).\n</li><li><strong>SW-C Template</strong>: Dokumenten-/Artefaktcontainer, der die Software-Komponente <code>Sensor SW-C</code> kapselt. Diese Softwarekomponente besitzt zwei Ports mit standardisierter Schnittstellennotation (P-Port / R-Port mit Lollipop- bzw. Socket-Symbolik an gelben und grünen Port-Rechtecken).\n</li><li><strong>reference</strong>: Gestrichelte gerichtete Beziehung (Abhängigkeits-/Referenzpfeil mit offener Pfeilspitze) von <code>Sensor SW-C</code> auf die Hardware-Entität <code>Sensor</code> im ECU Resource Template.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodell-Referenzierungsdiagramm ohne zeitlichen Sequenzablauf. Es beschreibt die deklarative Zuordnung: Die Softwarekomponente <code>Sensor SW-C</code> verweist über eine formale Referenz (<code>reference</code>) auf die korrespondierende Hardware-Ressourcenbeschreibung <code>Sensor</code>, um deren Eigenschaften und Signale softwareseitig zu nutzen bzw. abzubilden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die ganzheitliche Beschreibung gelieferter Sensor-Module in AUTOSAR. Beim Shipment eines Sensors muss neben der eigentlichen Software-Komponenten-Beschreibung (<code>SW-C Template</code>) auch die entsprechende Hardware-Ressourcen-Spezifikation (<code>ECU Resource Template</code>) mitgeliefert und die Referenzbeziehung zwischen Software und Hardware-Ressource formal im XML-Modell aufgelöst werden.</p>"}, {"id": "FIG-c1e97055041187cc", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Modellierungsdiagramm zur Verknüpfung von Hardware- und Softwareressourcen in AUTOSAR Classic. Das Diagramm veranschaulicht das Zusammenspiel zwischen dem ECU Resource Template (Hardwareressourcenbeschreibung eines Steuergeräts/Sensors) und dem Software Component Template (SW-C Template) bei der Bereitstellung („Shipment“) einer Sensor-Komponente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ECU Resource Template</strong>: Dokumenten-/Artefaktcontainer, der die physische Hardwareressource <code>Sensor</code> beschreibt. Die Sensor-Entität verfügt über einen eingehenden physikalischen/elektrischen Signalfluss (Pfeil links) und einen ausgehenden Signalfluss (Pfeil rechts).\n</li><li><strong>SW-C Template</strong>: Dokumenten-/Artefaktcontainer, der die Software-Komponente <code>Sensor SW-C</code> kapselt. Diese Softwarekomponente besitzt zwei Ports mit standardisierter Schnittstellennotation (P-Port / R-Port mit Lollipop- bzw. Socket-Symbolik an gelben und grünen Port-Rechtecken).\n</li><li><strong>reference</strong>: Gestrichelte gerichtete Beziehung (Abhängigkeits-/Referenzpfeil mit offener Pfeilspitze) von <code>Sensor SW-C</code> auf die Hardware-Entität <code>Sensor</code> im ECU Resource Template.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodell-Referenzierungsdiagramm ohne zeitlichen Sequenzablauf. Es beschreibt die deklarative Zuordnung: Die Softwarekomponente <code>Sensor SW-C</code> verweist über eine formale Referenz (<code>reference</code>) auf die korrespondierende Hardware-Ressourcenbeschreibung <code>Sensor</code>, um deren Eigenschaften und Signale softwareseitig zu nutzen bzw. abzubilden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die ganzheitliche Beschreibung gelieferter Sensor-Module in AUTOSAR. Beim Shipment eines Sensors muss neben der eigentlichen Software-Komponenten-Beschreibung (<code>SW-C Template</code>) auch die entsprechende Hardware-Ressourcen-Spezifikation (<code>ECU Resource Template</code>) mitgeliefert und die Referenzbeziehung zwischen Software und Hardware-Ressource formal im XML-Modell aufgelöst werden.</p>"}], "trans": [{"from": "FIG-8ceca6e6a74515da", "to": "FIG-c1e97055041187cc", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
